Translate("frFR", "thousand-needles", {
	title = "Mille pointes",
	aliases = { "les Pointes", "les Mille pointes" },
	sections = {
		{
			title = "Résumé",
			text = [=[Mille pointes est un grand canyon de pierre rouge au sud des {link:the-barrens}Tarides{/link}. Son fond est sec et poussiéreux, et il s'en élève des centaines d'étroites aiguilles de roche, si hautes et si minces que les voyageurs ont nommé tout le pays d'après elles. Les {link:tauren}taurens{/link} l'atteignent par la {link:the-great-lift}Grande Élévation{/link} sur sa bordure nord, et depuis les mesas du {link:freewind-post}Poste de Librevent{/link} ils veillent sur le canyon. À l'est, la pierre cède la place aux {link:the-shimmering-flats}Salines{/link}, une plaine de sel aveuglante où gobelins et gnomes font courir des machines de leur fabrication. Des serpents des vents s'enroulent parmi les aiguilles, des wyvernes nichent sur les hauteurs de l'ouest, et des harpies hurlent dans les canyons du sud. C'est un pays magnifique, et dangereux.]=],
		},
		{
			title = "Origines",
			text = [=[Aucune chronique ne rapporte comment les aiguilles en vinrent à se dresser ainsi, ni quand les {link:the-shimmering-flats}Salines{/link} devinrent un désert de sel. Les taurens parcourent ces canyons depuis des générations, et les {link:centaurs}centaures{/link} les y chassaient comme ils les chassaient sur toutes les plaines de {link:kalimdor}Kalimdor{/link}. Les érudits qui viennent aux Salines remarquent que la frontière entre les bois verts de {link:feralas}Féralas{/link} et la pierre sèche des Pointes est étrangement nette, comme si une magie ancienne l'avait tracée. Aucun d'eux ne peut dire quelle était cette magie.]=],
		},
		{
			title = "Aujourd'hui",
			text = [=[Les taurens du {link:freewind-post}Poste de Librevent{/link} tiennent le cœur du canyon, mais ils ne tiennent guère plus. Les centaures Galak pillent leurs caravanes depuis la {link:splithoof-crag}Combe du Sabot fendu{/link} et le {link:camp-e-thok}Camp E'thok{/link}, et ils ont juré de tuer tout {link:tauren}tauren{/link} qui oserait chasser à l'ouest. Sur la {link:darkcloud-pinnacle}Cime de Noir-nuage{/link}, des guerriers du {link:grimtotem-clan}clan Totem sinistre{/link} gardent le cimetière de leurs morts et reçoivent des étrangers qui vont et viennent en secret. Le Poste de Librevent les surveille de près et leur fait moins confiance à chaque saison.

À l'est, les {link:the-shimmering-flats}Salines{/link} sont devenues le théâtre d'une longue rivalité. Sur {link:mirage-raceway}la Piste des mirages{/link}, une équipe gobeline et une équipe {link:gnomes}gnome{/link} font courir leurs voitures-fusées à travers le sel, et la moitié des coquins et des rêveurs du monde viennent regarder et parier. Au sud de la piste, des nains de la {link:explorers-league}Ligue des explorateurs{/link} creusèrent la terre au {link:the-rustmaul-dig-site}Site de fouilles de Rustmaul{/link}, et quelque chose creusa en retour : un essaim de grands insectes que la {link:horde}Horde{/link} appelle aujourd'hui les silithides. Sur la bordure nord, près de l'élévation, les huranes tiennent la garenne d'épines des {link:razorfen-downs}Souilles de Tranchebauge{/link}, et des cultistes en robe ont été vus sur les sentiers voisins.]=],
		},
		{
			title = "Habitants",
			text = [=[• {b}Les taurens.{/b} Des braves, des chasseurs et des chamans tiennent le {link:freewind-post}Poste de Librevent{/link} et le petit camp de chasse du {link:whitereach-post}Poste de Blanc-relais{/link}.
• {b}Les Totem sinistre.{/b} Un clan {link:tauren}tauren{/link} à part, qui tient la {link:darkcloud-pinnacle}Cime de Noir-nuage{/link} et se méfie de toutes les autres tribus.
• {b}Les centaures Galak.{/b} Des pillards qui tiennent la {link:splithoof-crag}Combe du Sabot fendu{/link} et le {link:camp-e-thok}Camp E'thok{/link} et font la guerre aux taurens.
• {b}Les gobelins et les gnomes de {link:mirage-raceway}la Piste des mirages{/link}.{/b} Mécaniciens, pilotes, bookmakers et parasites.
• {b}Les harpies.{/b} Les harpies Screeching nichent dans le Canyon des hurlements et dans la {link:roguefeather-den}Tanière des Volplumes{/link}.
• {b}Les silithides.{/b} Des insectes qui surgissent en essaims de la terre sous le {link:the-rustmaul-dig-site}Site de fouilles de Rustmaul{/link}.
• {b}Les bêtes.{/b} Serpents des vents, wyvernes, couguars, hyènes, basilics, scorpides et les grandes tortues du sel.]=],
		},
		{
			title = "Histoire",
			text = [=[• {b}Les années d'errance.{/b} Les tribus taurens traversèrent ces canyons au cours de leurs longues errances, pourchassées par les centaures. Beaucoup de taurens du {link:freewind-post}Poste de Librevent{/link} se souviennent encore de ces jours.
• {b}La conquête de Mulgore.{/b} Quand {link:cairne-bloodhoof}Cairne Bloodhoof{/link} mena son peuple en {link:mulgore}Mulgore{/link} avec l'aide de la {link:horde}Horde{/link}, les taurens devinrent assez forts pour revenir aux Pointes. Aucune chronique ne rapporte quand ils élevèrent le Poste de Librevent ou la {link:the-great-lift}Grande Élévation{/link}.
• {b}L'arrivée des coureurs.{/b} Les gobelins et les gnomes trouvèrent dans les {link:the-shimmering-flats}Salines{/link} le terrain le plus plat de {link:kalimdor}Kalimdor{/link}, et ils y bâtirent une piste de course.
• {b}Aujourd'hui.{/b} Les Galak s'enhardissent, {link:grimtotem-clan}les Totem sinistre{/link} gardent leurs secrets, et les silithides sont sortis de la terre.]=],
		},
		{
			title = "Savoir des Pointes",
			text = [=[• Les taurens du {link:whitereach-post}Poste de Blanc-relais{/link} connaissent la légende d'{link:arikara}Arikara{/link}, un serpent de vengeance qui surgit du feu sacré de la {link:darkcloud-pinnacle}Cime de Noir-nuage{/link} contre ceux qui ont commis des actes odieux. La plupart n'y voyaient qu'une légende.
• Les Galak gardent une relique datant de l'époque où naquirent les premiers centaures, conservée dans une caverne derrière une flamme qui ne s'éteint jamais.
• Une hyène que les taurens appellent {link:steelsnap}Steelsnap{/link} rassemble d'autres hyènes autour d'elle et répand la peur parmi les bêtes plus paisibles du canyon.
• Les équipes des stands de {link:mirage-raceway}la Piste des mirages{/link} disent que chaque étendue des {link:the-shimmering-flats}Salines{/link} est jonchée d'épaves de voitures-fusées, et qu'un récupérateur soigneux peut en vivre.]=],
		},
	},
})

Translate("frFR", "freewind-post", {
	title = "Poste de Librevent",
	aliases = { "Librevent" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le Poste de Librevent est la place forte des taurens à {link:thousand-needles}Mille pointes{/link}, élevée sur un groupe de mesas au milieu du canyon. Des ponts de corde et de bois relient le sommet des mesas, et une élévation porte les voyageurs depuis le fond du canyon. Le garde-falaise Longhorn commande ses braves. L'aubergiste Abeqwa tient la hutte, Montarr garde le savoir des tribus, et les coursiers du vent de Nyse portent les nouvelles à {link:thunder-bluff}Thunder Bluff{/link} et à {link:the-crossroads}La Croisée{/link}. Sur un poteau près de la hutte pend un avis que chaque brave a lu : une récompense pour le paria Totem sinistre {link:arnak-grimtotem}Arnak{/link}. Depuis ses hauteurs, les taurens voient les camps Galak au nord et la cime des Totem sinistre au nord-ouest.]=],
		},
	},
})

Translate("frFR", "the-great-lift", {
	title = "La Grande Élévation",
	aliases = { "Grande Élévation" },
	sections = {
		{
			title = "Résumé",
			text = [=[La Grande Élévation relie la bordure sud des {link:the-barrens}Tarides{/link} au fond de {link:thousand-needles}Mille pointes{/link}, loin en contrebas. Les taurens l'ont bâtie, et ses plates-formes montent et descendent au bout de longues cordes le long de la falaise. C'est la seule route facile vers le canyon depuis le nord, et elle est donc gardée. Grish Longrunner la surveille depuis si longtemps qu'il l'appelle un tas de bois, et il attend depuis de nombreuses saisons d'être relevé pour pouvoir rendre visite à sa famille. Le brave Moonhorn surveille le sentier en contrebas, où les raids des centaures sont devenus plus fréquents depuis peu.]=],
		},
	},
})

Translate("frFR", "whitereach-post", {
	title = "Poste de Blanc-relais",
	aliases = { "Blanc-relais" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le Poste de Blanc-relais est un petit camp {link:tauren}tauren{/link} au nord-ouest du canyon, au sud-ouest de la {link:the-great-lift}Grande Élévation{/link}, le long de la route de {link:freewind-post}Librevent{/link}. {link:kanati-greycloud}Kanati Greycloud{/link} l'a installé comme camp de chasse, assez hardi pour chasser dans les canyons de l'ouest que revendiquent les Galak. {link:motega-firemane}Motega Firemane{/link} est venu ici avec le jeune {link:pao-ka-swiftmountain}Pao'ka Swiftmountain{/link} pour étudier les créatures des Pointes. Un bricoleur gobelin, {link:wizlo-bearingshiner}Wizlo Bearingshiner{/link}, a trouvé refuge parmi eux après que les centaures ont détruit sa caravane. Les Galak comptent balayer le camp, et ses quelques tentes sont toujours surveillées.]=],
		},
	},
})

Translate("frFR", "darkcloud-pinnacle", {
	title = "Cime de Noir-nuage",
	sections = {
		{
			title = "Résumé",
			text = [=[La Cime de Noir-nuage est un groupe d'aiguilles au nord-ouest du canyon, tenu par le {link:grimtotem-clan}clan Totem sinistre{/link}. Des sentiers et des ponts grimpent parmi ses flèches, et sur une aiguille isolée les Totem sinistre enterrent leurs morts près d'un feu sacré de vie longtemps resté dormant. Le clan garde farouchement ce lieu. Des agents d'origine inconnue l'ont visité en secret, laissant des lettres scellées dans les coffres des Totem sinistre. {link:arnak-grimtotem}Arnak{/link} le paria rôde sur les falaises voisines, et c'est ici qu'il amena la taurène qu'il avait enlevée.]=],
		},
	},
})

Translate("frFR", "splithoof-crag", {
	title = "Combe du Sabot fendu",
	aliases = { "Bastion du Sabot fendu" },
	sections = {
		{
			title = "Résumé",
			text = [=[La Combe du Sabot fendu est la place forte des {link:centaurs}centaures{/link} Galak, un village de tentes de peau adossé à la paroi nord du canyon, à l'est de la {link:darkcloud-pinnacle}Cime de Noir-nuage{/link} et au nord du {link:freewind-post}Poste de Librevent{/link}. Ses pillards partent à l'assaut des caravanes taurens, et ses éclaireurs poussent jusqu'au bord même des mesas de Librevent. Au fond de la combe s'ouvre le Bastion du Sabot fendu, une caverne gardée. Là, derrière un antique brasero dont la flamme ne meurt jamais, les Galak conservent le Cloven Hoof, une relique de l'époque où naquit leur race.]=],
		},
	},
})

Translate("frFR", "camp-e-thok", {
	title = "Camp E'thok",
	sections = {
		{
			title = "Résumé",
			text = [=[Le Camp E'thok est un camp de guerre Galak à l'extrême nord-ouest de {link:thousand-needles}Mille pointes{/link}, non loin en contrebas des {link:the-barrens}Tarides{/link}. Près de lui gisent les chariots brisés d'une caravane gobeline que les centaures attaquèrent et pillèrent. Ils prirent tout sauf une panthère en cage, une bête si féroce que même les centaures la craignent. Autour du cou de la panthère pend encore le précieux appareil de {link:wizlo-bearingshiner}Wizlo Bearingshiner{/link}, seul survivant de la caravane. La hyène {link:steelsnap}Steelsnap{/link} et sa meute rôdent sur les pentes voisines.]=],
		},
	},
})

Translate("frFR", "highperch", {
	title = "Haut-perchoir",
	sections = {
		{
			title = "Résumé",
			text = [=[Haut-perchoir est une haute corniche rocheuse sur la bordure ouest du canyon, que l'on atteint par une rampe le long des parois de la falaise. C'est le lieu de nidification des wyvernes de Haut-perchoir, et elles défendent leurs œufs avec une dévotion sauvage. Les taurens de {link:freewind-post}Librevent{/link} y récoltent des œufs pour élever de nouvelles montures destinées aux coursiers du vent de la {link:horde}Horde{/link}. D'autres viennent chercher le venin des wyvernes, qui se vend cher dans certains milieux. Une grande wyverne que les chasseurs appellent Heartrazor règne sur le ciel au-dessus des nids.]=],
		},
	},
})

Translate("frFR", "roguefeather-den", {
	title = "Tanière des Volplumes",
	sections = {
		{
			title = "Résumé",
			text = [=[La Tanière des Volplumes est une grotte au sud du canyon, à l'ouest du {link:freewind-post}Poste de Librevent{/link}, au bout du Canyon des hurlements. Les {link:harpies}harpies{/link} Screeching y nichent, et au fond de la tanière elles entassent la nourriture qu'elles ont volée dans le canyon. Leur matriarche, {link:grenka-bloodscreech}Grenka Bloodscreech{/link}, ne se montre pas aux étrangers, mais ceux qui gâtent les réserves des harpies apprennent vite avec quelle rapidité elle arrive. C'est pourquoi les taurens qui mettent les jeunes à l'épreuve les envoient ici pour prouver leur endurance.]=],
		},
	},
})

Translate("frFR", "windbreak-canyon", {
	title = "Canyon de Brisevent",
	sections = {
		{
			title = "Résumé",
			text = [=[Le Canyon de Brisevent longe le côté nord de la route entre le {link:freewind-post}Poste de Librevent{/link} et les {link:the-shimmering-flats}Salines{/link}. Des serpents des vents nichent dans ses antres au pied des falaises, et ils s'enroulent au-dessus des aiguilles au crépuscule. Dans l'un de ces antres, on trouva les serpents gardant un œuf qui n'était pas le leur. Sur une hauteur solitaire près du canyon vit {link:dorn-plainstalker}Dorn Plainstalker{/link}, qui met à l'épreuve les jeunes de toutes les tribus, et près de lui demeure la chamane {link:prate-cloudseer}Prate Cloudseer{/link}, qui parle pour les esprits de l'air.]=],
		},
	},
})

Translate("frFR", "the-shimmering-flats", {
	title = "Les Salines",
	aliases = { "Salines" },
	sections = {
		{
			title = "Résumé",
			text = [=[Les Salines emplissent le sud-est de {link:thousand-needles}Mille pointes{/link} : une plaine de sel blanc si plate et si brillante que l'air au-dessus tremble de chaleur. Des scorpides incrustés de sel, des basilics, des vautours et de grandes tortues scintillantes y vivent, et ils deviennent plus grands que quiconque ne peut l'expliquer. Les gobelins et les gnomes ont fait des Salines leur terrain de course, et le tonnerre de leurs moteurs résonne contre les parois du canyon. Sur sa bordure sud, les nains creusèrent le {link:the-rustmaul-dig-site}Site de fouilles de Rustmaul{/link}. Sur sa frontière nord, un groupe de guerre de la {link:horde}Horde{/link} mal en point monte la garde.]=],
		},
	},
})

Translate("frFR", "mirage-raceway", {
	title = "Piste des mirages",
	aliases = { "la Piste des mirages", "la Piste" },
	sections = {
		{
			title = "Résumé",
			text = [=[La Piste des mirages est un circuit tracé sur les {link:the-shimmering-flats}Salines{/link}, avec les stands de deux équipes rivales à chaque extrémité d'une tribune. Les gobelins construisent leurs bolides avec deux moteurs et plus de feu que de bon sens. Les gnomes, menés par les frères Brassbolts, construisent avec soin et s'écrasent quand même. Le maître de course {link:race-master-kronkrider}Kronkrider{/link} règne sur la piste, des annonceurs crient les cotes, et des marchands vendent boissons et glaces à la foule. Derrière le bruit, il y a de l'argent, et là où il y a de l'argent, il y a des manigances : plans volés, équipes soudoyées et pilotes aux secrets bien gardés.]=],
		},
	},
})

Translate("frFR", "the-rustmaul-dig-site", {
	title = "Site de fouilles de Rustmaul",
	aliases = { "Site de fouilles de Rustmaul" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le Site de fouilles de Rustmaul se trouve à la bordure sud des {link:the-shimmering-flats}Salines{/link}, là où une équipe de fouilles de la {link:explorers-league}Ligue des explorateurs{/link} entailla la terre. La {link:horde}Horde{/link} envoya un groupe de guerre pour chasser les nains. Le raid réussit, mais en plein combat un essaim de grands insectes jaillit d'une grotte à l'intérieur des fouilles, et plus de la moitié des orcs ne revinrent jamais. Les nains sont partis. Les insectes demeurent, et leur nombre grandit : chercheurs, bourdons et envahisseurs aux carapaces plus solides que toute armure connue des forgerons de la Horde.]=],
		},
	},
})

Translate("frFR", "cliffwatcher-longhorn", {
	title = "Garde-falaise Longhorn",
	subtitle = "Commandant du Poste de Librevent",
	found = "Poste de Librevent",
	hint = [=[Parlez au garde-falaise qui commande les braves du Poste de Librevent.]=],
	allegiance = "Horde · Poste de Librevent",
	sections = {
		{
			title = "Résumé",
			text = [=[Le garde-falaise Longhorn commande les braves du {link:freewind-post}Poste de Librevent{/link}. Depuis les hautes mesas, il surveille tout {link:thousand-needles}Mille pointes{/link}, et rien de ce qu'il y voit ne lui plaît. Les Galak pillent ses caravanes, {link:grimtotem-clan}les Totem sinistre{/link} gardent leurs secrets sur la {link:darkcloud-pinnacle}Cime de Noir-nuage{/link}, et un meurtrier de ce clan erre en liberté sur les falaises. C'est un chef dur et coléreux, lent à pardonner un tort fait à son peuple.]=],
		},
		{
			title = "Importance",
			text = [=[Longhorn est le premier à voir la forme des troubles qui s'amassent sur {link:thousand-needles}les Pointes{/link}. Les centaures n'en sont que la partie la plus bruyante. Sa découverte que {link:grimtotem-clan}les Totem sinistre{/link} traitent avec des étrangers venus d'au-delà de {link:kalimdor}Kalimdor{/link} est un avertissement qui porte bien au-delà d'un seul canyon.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il jura de se venger des Galak quand ils massacrèrent l'une de ses caravanes de ravitaillement.
• Il mit à prix la tête d'{link:arnak-grimtotem}Arnak Grimtotem{/link} pour meurtre et enlèvement.
• Il envoya des espions sur la {link:darkcloud-pinnacle}Cime de Noir-nuage{/link} pour apprendre ce que cachaient {link:grimtotem-clan}les Totem sinistre{/link}.
• Il tient son frère Nataka, loin en {link:desolace}Désolace{/link}, informé des mouvements des centaures.]=],
		},
		{
			title = "Non consigné",
			text = [=[On a peu écrit sur la vie de Longhorn avant le {link:freewind-post}Poste de Librevent{/link}. On sait seulement qu'il a un frère, Nataka, qui sert au {link:ghost-walker-post}Poste de Rôdeur-fantôme{/link} en {link:desolace}Désolace{/link}, et qu'une année s'écoula entre deux de ses lettres à celui-ci.]=],
		},
	},
	chapters = {
		{
			title = "La colère de Librevent",
			hint = [=[Portez le message urgent de la Grande Élévation au Poste de Librevent.]=],
			text = [=[Un brave de la {link:the-great-lift}Grande Élévation{/link} fit savoir que les centaures avaient repris leurs raids. La nouvelle arriva trop tard pour l'une des caravanes de Longhorn : les Galak l'avaient déjà attaquée et avaient tué chaque {link:tauren}tauren{/link} qui l'accompagnait. Longhorn parla d'un outrage et jura qu'il ne resterait pas impuni. Il envoya tous les guerriers volontaires contre le camp Galak au nord du poste.]=],
		},
		{
			title = "Les lettres secrètes",
			hint = [=[Apprenez ce que cachent les Totem sinistre sur la Cime de Noir-nuage.]=],
			text = [=[Pendant plusieurs semaines, trois étrangers d'origine inconnue avaient été vus rendant visite aux Totem sinistre. Longhorn apprit que chacun avait laissé un message dans un coffre différent sur la {link:darkcloud-pinnacle}Cime de Noir-nuage{/link}, et il les fit prendre. Les lettres étaient adressées à un certain Agasham et signées par trois individus qui se nommaient les Hérauts. Elles parlaient d'une alliance que les autres tribus taurens ne devaient jamais découvrir, d'une obéissance totale, et d'agents de {link:lordaeron}Lordaeron{/link} qui rencontreraient bientôt les délégués d'Agasham. Longhorn les lut et jugea la nouvelle funeste. Il commença à se préparer à ce qui pourrait advenir.]=],
		},
	},
	mentions = {
		{
			text = [=[Message pour le {link:freewind-post}Poste de Librevent{/link}, apporté par le messager du brave Moonhorn]=],
		},
		{ text = "Pacifier les centaures" },
		{ text = "Espionner {link:grimtotem-clan}les Totem sinistre{/link}" },
		{
			text = [=[Avis de recherche : {link:arnak-grimtotem}Arnak Grimtotem{/link}]=],
		},
		{ text = "Arbre généalogique, un rapport pour son frère" },
	},
	bonds = {
		{ id = "arnak-grimtotem", name = "Arnak Grimtotem", note = "le paria qu'il veut voir traduit en justice" },
		{ id = "hagar-lightninghoof", name = "Hagar Lightninghoof", note = "sert au Poste de Librevent" },
		{ id = "thalia-amberhide", name = "Thalia Amberhide", note = "sert au Poste de Librevent" },
		{ id = "nataka-longhorn", name = "Nataka Longhorn", note = "son frère en Désolace" },
		{ id = "magatha-grimtotem", name = "Magatha Grimtotem", note = "doyenne du clan qu'il surveille" },
	},
})

Translate("frFR", "hagar-lightninghoof", {
	title = "Hagar Lightninghoof",
	subtitle = "Érudit du Poste de Librevent",
	found = "Poste de Librevent",
	hint = [=[Parlez au tauren du Poste de Librevent qu'intrigue un œuf étrange.]=],
	allegiance = "Horde · Poste de Librevent",
	aliases = { "Hagar" },
	sections = {
		{
			title = "Résumé",
			text = [=[Hagar Lightninghoof est un {link:tauren}tauren{/link} du {link:freewind-post}Poste de Librevent{/link} avide d'inconnu. Quand lui parvinrent des rumeurs d'un œuf étrange gardé par les serpents des vents, il voulut le voir de ses propres yeux. Il le fit apporter à Librevent, et il le vit éclore.]=],
		},
		{
			title = "Importance",
			text = [=[Ce qui sortit de l'œuf était un jeune serpent de vengeance, et Hagar comprit aussitôt que la vieille légende d'{link:arikara}Arikara{/link} était vraie. Son alarme lança les taurens des Pointes sur la piste du serpent.]=],
		},
	},
	chapters = {
		{
			title = "L'œuf étranger",
			hint = "Apportez à Hagar l'œuf étrange des antres des serpents.",
			text = [=[L'œuf reposait dans un antre de serpents au pied des falaises, et les serpents le gardaient comme s'il était l'un des leurs. Quand on le lui apporta, Hagar se pencha pour l'étudier. Il se brisa sous ses yeux. Il s'essuya le front et dit que la vengeance était venue à {link:thousand-needles}Mille pointes{/link}, et il fit aussitôt prévenir {link:motega-firemane}Motega Firemane{/link}.]=],
		},
	},
	mentions = {
		{ text = "L'œuf étranger" },
		{ text = "Serpent sauvage" },
	},
	bonds = {
		{ id = "motega-firemane", name = "Motega Firemane", note = "connaissait la légende" },
		{ id = "arikara", name = "Arikara", note = "éclos sous ses yeux" },
	},
})

Translate("frFR", "thalia-amberhide", {
