Translate("frFR", "rau-cliffrunner", {
	title = "Rau Cliffrunner",
	subtitle = "Chercheur du Cloven Hoof",
	found = "Poste de Librevent",
	hint = [=[Parlez au tauren du Poste de Librevent qui étudie les centaures.]=],
	allegiance = "Horde · Poste de Librevent",
	aliases = { "Rau" },
	sections = {
		{
			title = "Résumé",
			text = [=[Rau Cliffrunner est un {link:tauren}tauren{/link} du {link:freewind-post}Poste de Librevent{/link} qui veut comprendre les centaures, et pas seulement les combattre. Avec son associé Zangen Stonehoof de {link:thunder-bluff}Thunder Bluff{/link}, il entreprit de s'emparer du Cloven Hoof, une relique que les Galak gardent depuis l'époque de la création de leur peuple.]=],
		},
		{
			title = "Importance",
			text = [=[Rau trouva la clé des défenses des centaures dans leur propre ascendance. Parce que les dryades et les centaures partagent une origine commune, l'eau d'un puits de lune des elfes de la nuit pouvait percer la flamme éternelle qui gardait la relique.]=],
		},
	},
	chapters = {
		{
			title = "La flamme sacrée",
			hint = [=[Portez une fiole d'eau de puits de lune au Poste de Librevent et utilisez-la dans le Bastion du Sabot fendu.]=],
			text = [=[L'eau du puits de lune n'éteindrait la flamme du {link:splithoof-crag}Bastion du Sabot fendu{/link} que peu de temps. Ce fut assez. Le Cloven Hoof fut emporté hors de la place forte des centaures, et Rau sentit une étrange énergie circuler en lui. Il croit qu'il apprendra aux taurens des choses surprenantes sur les centaures, et il a commencé à le déchiffrer.]=],
		},
	},
	mentions = {
		{ text = "La flamme sacrée" },
		{ text = "La flamme sacrée, le Cloven Hoof" },
	},
	bonds = {
		{ id = "zangen-stonehoof", name = "Zangen Stonehoof", note = "son associé à Thunder Bluff" },
	},
})

Translate("frFR", "motega-firemane", {
	title = "Motega Firemane",
	subtitle = "Gardien du Poste de Blanc-relais",
	found = "Poste de Blanc-relais",
	hint = [=[Parlez au tauren qui étudie les créatures des Pointes au Poste de Blanc-relais.]=],
	allegiance = "Horde · Poste de Blanc-relais",
	aliases = { "Motega" },
	sections = {
		{
			title = "Résumé",
			text = [=[Motega Firemane vint à {link:thousand-needles}Mille pointes{/link} pour étudier les créatures qui y vivent, et il amena avec lui le jeune {link:pao-ka-swiftmountain}Pao'ka Swiftmountain{/link}. Il a planté ses tentes au {link:whitereach-post}Poste de Blanc-relais{/link}, au nord-ouest du canyon. Motega connaît les vieux récits des taurens mieux que la plupart, et quand un serpent de légende revint aux Pointes, c'est vers lui que les taurens se tournèrent.]=],
		},
		{
			title = "Importance",
			text = [=[Motega est le lien entre {link:thousand-needles}les Pointes{/link} et la doyenne. C'est lui qui prévint {link:magatha-grimtotem}Magatha Grimtotem{/link} au sujet du serpent {link:arikara}Arikara{/link}, et lui qui reçut la poudre qui l'appellerait hors du feu sacré. Il fut aussi le premier à trouver son avertissement étrange.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il étudie les créatures de {link:thousand-needles}Mille pointes{/link} depuis le {link:whitereach-post}Poste de Blanc-relais{/link}.
• Il veille sur {link:pao-ka-swiftmountain}Pao'ka Swiftmountain{/link}, dont le père hésitait à laisser venir le garçon.
• Il connaît la légende d'{link:arikara}Arikara{/link}, le serpent né pour venger les actes odieux.
• Il demanda l'aide de {link:magatha-grimtotem}Magatha{/link} pour raviver le feu sacré dormant de la {link:darkcloud-pinnacle}Cime de Noir-nuage{/link}.]=],
		},
		{
			title = "Non consigné",
			text = [=[On a peu écrit sur la vie de Motega avant le {link:whitereach-post}Poste de Blanc-relais{/link}. Qui est le père de {link:pao-ka-swiftmountain}Pao'ka{/link}, et pourquoi il confia le garçon à Motega, n'est pas rapporté.]=],
		},
	},
	chapters = {
		{
			title = "Le garçon perdu",
			hint = "Ramenez Pao'ka de Haut-perchoir.",
			text = [=[{link:pao-ka-swiftmountain}Pao'ka{/link} partit seul à {link:highperch}Haut-perchoir{/link} étudier les wyvernes et ne revint pas. Quand le garçon fut enfin ramené, Motega était furieux. Il dit que s'il avait su, il l'aurait enchaîné à un totem. Sous la colère, il était reconnaissant, et il récompensa ceux qui avaient aidé.]=],
		},
		{
			title = "La légende d'Arikara",
			hint = "Répondez à l'avertissement d'Hagar Lightninghoof.",
			text = [=[Motega avait entendu parler d'{link:arikara}Arikara{/link} toute sa vie sans jamais croire qu'il la verrait. À présent, la légende était vraie. Pour chasser le serpent, il fallait allumer le feu sacré de vie sur la {link:darkcloud-pinnacle}Cime de Noir-nuage{/link}, et seul un chaman puissant pouvait enchanter le rare agave Incendia qui l'allumerait. Motega envoya l'agave récolté à {link:magatha-grimtotem}Magatha Grimtotem{/link} à {link:thunder-bluff}Thunder Bluff{/link}.]=],
		},
		{
			title = "Une réponse troublante",
			hint = "Tuez Arikara et retournez au Poste de Blanc-relais.",
			text = [=[La doyenne avait averti qu'{link:arikara}Arikara{/link} traquait peut-être {link:cairne-bloodhoof}Cairne Bloodhoof{/link}, irritée parce que trop de l'ancien savoir des taurens avait changé. Quand le serpent fut tué, Motega secoua la tête. Il ne voyait aucun sens à ce qu'Arikara chasse le grand chef. Pourtant, il ne voulut pas dire que {link:magatha-grimtotem}Magatha{/link} se trompait. Elle était, dit-il, la plus puissante d'entre eux.]=],
		},
	},
	mentions = {
		{ text = "Le chemin du retour" },
		{ text = "Serpent sauvage" },
		{ text = "Feu sacré" },
		{ text = "{link:arikara}Arikara{/link}" },
	},
	bonds = {
		{ id = "pao-ka-swiftmountain", name = "Pao'ka Swiftmountain", note = "le garçon dont il a la charge" },
		{ id = "hagar-lightninghoof", name = "Hagar Lightninghoof", note = "lui apporta la nouvelle" },
		{ id = "magatha-grimtotem", name = "Magatha Grimtotem", note = "enchanta la poudre" },
		{ id = "arikara", name = "Arikara", note = "le serpent de légende" },
		{ id = "kanati-greycloud", name = "Kanati Greycloud", note = "partage le Poste de Blanc-relais" },
	},
})

Translate("frFR", "pao-ka-swiftmountain", {
	title = "Pao'ka Swiftmountain",
	subtitle = "Jeune érudit des wyvernes",
	found = "Haut-perchoir",
	hint = [=[Cherchez le jeune tauren perdu parmi les nids de wyvernes de Haut-perchoir.]=],
