	allegiance = "Clan Totem sinistre (paria)",
	aliases = { "Arnak" },
	sections = {
		{
			title = "Résumé",
			text = [=[Arnak est un paria du {link:grimtotem-clan}clan Totem sinistre{/link}, recherché au {link:freewind-post}Poste de Librevent{/link} pour meurtre et enlèvement. Il demanda à {link:lakota-windsong}Lakota Windsong{/link} d'être sa compagne, et elle le repoussa. La nuit même, il revint et l'emmena de force. Le frère de Lakota tenta de l'en empêcher, et Arnak le tua. Puis il emporta Lakota sur la {link:darkcloud-pinnacle}Cime de Noir-nuage{/link}.]=],
