	},
})

Translate("frFR", "arikara", {
	title = "Arikara",
	subtitle = "Serpent de vengeance",
	found = "Le feu sacré de la Cime de Noir-nuage",
	hint = [=[Ravivez le feu sacré là où les Totem sinistre enterrent leurs morts.]=],
	allegiance = "Aucune",
	sections = {
		{
			title = "Résumé",
			text = [=[Arikara est un serpent de la légende taurène, une créature née, dit-on, uniquement pour chercher vengeance contre ceux qui ont commis des actes odieux. Le feu sacré de vie de la {link:darkcloud-pinnacle}Cime de Noir-nuage{/link}, dormant depuis de longues années, peut l'appeler. En ces jours, son œuf fut trouvé dans un antre de serpents des Pointes, et il éclot au {link:freewind-post}Poste de Librevent{/link}.]=],
		},
		{
			title = "Importance",
			text = [=[Arikara est une légende qui a pris corps. {link:magatha-grimtotem}Magatha Grimtotem{/link} avertit que le serpent traquait peut-être le grand chef {link:cairne-bloodhoof}Cairne Bloodhoof{/link}, irrité par les changements apportés à l'ancien savoir des taurens. Certains au {link:whitereach-post}Poste de Blanc-relais{/link} trouvèrent cet avertissement difficile à comprendre.]=],
