		{ id = "motega-firemane", name = "Motega Firemane", note = "connaissait sa légende" },
		{ id = "hagar-lightninghoof", name = "Hagar Lightninghoof", note = "vit éclore son petit" },
	},
})

Translate("frFR", "dorn-plainstalker", {
	title = "Dorn Plainstalker",
	subtitle = "Celui qui éprouve les jeunes",
	found = "Une hauteur solitaire au nord-est du Poste de Librevent",
	hint = [=[Cherchez le tauren qui éprouve les jeunes sur une hauteur solitaire au-dessus des Pointes.]=],
	allegiance = "Horde",
	aliases = { "Dorn" },
	sections = {
		{
			title = "Résumé",
			text = [=[Dorn Plainstalker vit seul sur une hauteur au-dessus des Pointes, loin de l'agitation du {link:freewind-post}Poste de Librevent{/link}. Il considère comme son devoir de préparer les jeunes de toutes les tribus aux dangers qu'ils rencontreront une fois quitté l'abri du foyer. Il les éprouve en trois choses : l'esprit, le corps et l'intellect. Ceux qui réussissent reviennent plus forts. Ceux qui échouent, dit-il, apprennent combien le monde est vaste en vérité.]=],
		},
		{
			title = "Importance",
			text = [=[Dorn est un maître à l'ancienne. Peu lui importe de quelle tribu vient un guerrier, seulement que ce guerrier soit prêt. Ses épreuves relient plusieurs sages de la {link:horde}Horde{/link} à travers {link:kalimdor}Kalimdor{/link} et au-delà.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il éprouve la foi, l'endurance, la force et le savoir des jeunes.
• Il les envoie contre la matriarche des harpies de la {link:roguefeather-den}Tanière des Volplumes{/link} et contre l'élémentaire {link:rok-alim-the-pounder}Rok'Alim{/link}.
• Il les envoie ensuite auprès du chaman {link:braug-dimspirit}Braug Dimspirit{/link} dans les {link:stonetalon-mountains}Serres-Rocheuses{/link} pour l'épreuve du savoir.]=],
		},
		{
			title = "Non consigné",
			text = [=[On a peu écrit sur la vie de Dorn ni sur le temps depuis lequel il garde sa hauteur. Sa tribu n'est pas nommée.]=],
		},
	},
	chapters = {
		{
			title = "Le saut de la foi",
			hint = "Prouvez votre foi sur la hauteur de Dorn.",
			text = [=[La première épreuve de Dorn est la plus étrange. Il demande aux jeunes de sauter des planches de sa hauteur dans le vide, sans promesse de survie. La foi, enseigne-t-il, compte plus que beaucoup ne le pensent. Ce qui importe n'est pas toujours ce que l'on croit, mais que l'on croie en quelque chose.]=],
		},
		{
			title = "Le corps et la force",
			hint = "Réussissez les épreuves d'endurance et de force.",
			text = [=[Pour le corps, Dorn envoie les jeunes dans la {link:roguefeather-den}Tanière des Volplumes{/link} gâter les réserves des harpies et affronter {link:grenka-bloodscreech}Grenka Bloodscreech{/link} quand elle arrive dans sa fureur. Pour la force, il les envoie contre {link:rok-alim-the-pounder}Rok'Alim{/link}, un élémentaire qui s'attarde sur {link:thousand-needles}les Pointes{/link} depuis l'âge des Dieux très anciens.]=],
		},
		{
			title = "L'ultime passage",
			hint = "Achevez l'épreuve du savoir et retournez auprès de Dorn.",
			text = [=[L'épreuve du savoir n'est pas la sienne à donner. Elle passe par {link:braug-dimspirit}Braug Dimspirit{/link} dans les {link:stonetalon-mountains}Serres-Rocheuses{/link} et au-delà, jusqu'à des érudits loin des Pointes. Quand les jeunes reviennent enfin auprès de Dorn, il les regarde comme si bien des lunes s'étaient écoulées depuis leur premier saut, et il leur dit que leur intellect, leur corps et leur esprit sont forts.]=],
