Translate("frFR", "moktar-krin", {
	title = "Moktar Krin",
	subtitle = "Chef d'un groupe de guerre brisé",
	found = "La frontière nord des Salines",
	hint = [=[Trouvez l'orc qui tient un camp de guerre à la frontière des Salines.]=],
	allegiance = "Horde · Orgrimmar",
	aliases = { "Moktar" },
	sections = {
		{
			title = "Résumé",
			text = [=[Moktar Krin mena un groupe de guerre de la {link:horde}Horde{/link} pour chasser les nains de la {link:explorers-league}Ligue des explorateurs{/link} des {link:the-shimmering-flats}Salines{/link}. Les nains moururent, mais pendant le combat un essaim d'insectes jaillit d'une grotte à l'intérieur des fouilles et tua plus de la moitié de ses guerriers. Aujourd'hui, il tient son camp à la frontière des Salines avec une bande trop meurtrie pour marcher. Il attend les ordres de Belgrom Rockmaul à {link:orgrimmar}Orgrimmar{/link}, et il surveille le sud.]=],
		},
		{
			title = "Importance",
			text = [=[Moktar fut le premier de la {link:horde}Horde{/link} à rencontrer les silithides sur {link:thousand-needles}les Pointes{/link}, et il le paya. Son rapport, porté à Korran à {link:the-crossroads}La Croisée{/link}, aida la Horde à commencer à comprendre les insectes.]=],
		},
	},
	chapters = {
		{
			title = "L'essaim grandit",
			hint = "Repoussez les insectes du Site de fouilles de Rustmaul.",
			text = [=[Belgrom voulait que les insectes soient repoussés dans les profondeurs d'où ils étaient venus. Les guerriers de Moktar ne pouvaient y parvenir seuls. Avec l'aide de voyageurs qui se rendaient aux courses, l'essaim fut éclairci, et les carapaces prises sur les morts furent envoyées à Korran pour être étudiées.]=],
		},
	},
	mentions = {
		{ text = "L'essaim grandit" },
		{ text = "L'essaim grandit" },
		{ text = "Morceaux de l'essaim" },
	},
	bonds = {
		{ id = "korran", name = "Korran", note = "étudie les insectes à La Croisée" },
		{ id = "belgrom-rockmaul", name = "Belgrom Rockmaul", note = "son commandant à Orgrimmar" },
	},
})

Translate("frFR", "pozzik", {
	title = "Pozzik",
	subtitle = "Chef mécanicien des coureurs gobelins",
	found = "Les stands gobelins de la Piste des mirages",
	hint = [=[Parlez au mécanicien gobelin dans les stands gobelins de la Piste des mirages.]=],
	allegiance = "Cartel Gentepression · Équipe de course gobeline",
	sections = {
		{
			title = "Résumé",
			text = [=[Pozzik fut autrefois l'un des bricoleurs les plus respectés d'Undermine. Il laissa derrière lui le Tinkers' Union pour travailler sur les bolides, et la première chose qu'il fit fut de concevoir les modèles à deux moteurs que l'équipe gobeline pilote encore. Aujourd'hui, il dirige ses mécaniciens sur les {link:the-shimmering-flats}Salines{/link}. Il pèse chaque boulon et chaque os, car en course chaque once compte.]=],
		},
		{
			title = "Importance",
			text = [=[Pozzik est le cerveau de l'équipe gobeline, et il est en train de perdre. Les gnomes le rattrapent, et il ferait presque n'importe quoi pour suivre le rythme : faire appel aux barons et aux constructeurs gobelins qui le parrainent, et voler ses rivaux s'il le faut.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il conçut les bolides gobelins à deux moteurs.
• Il construit ses châssis avec les os creux des vautours des {link:the-shimmering-flats}Salines{/link}.
• Il chercha un nouveau régulateur de carburant par l'entremise de {link:gazlowe}Gazlowe{/link} de {link:ratchet}Ratchet{/link} et du baron {link:baron-revilgaz}Revilgaz{/link} de {link:booty-bay}Baie-du-Butin{/link}.
• Il fit voler les plans de Rizzle Brassbolts, et y apprit le secret de l'indurium.]=],
		},
		{
			title = "Non consigné",
			text = [=[On a peu écrit sur les années de Pozzik à Undermine ni sur les raisons de son départ.]=],
		},
	},
	chapters = {
		{
			title = "Parrainage gobelin",
			hint = [=[Découvrez ce qu'il advint du régulateur de carburant promis à Pozzik.]=],
			text = [=[{link:gazlowe}Gazlowe{/link} avait promis un nouveau régulateur de carburant, et il n'arriva jamais. La piste mena de {link:ratchet}Ratchet{/link} aux quais de {link:booty-bay}Baie-du-Butin{/link} et au baron {link:baron-revilgaz}Revilgaz{/link}, qui admit que ses hommes n'avaient pas réussi à trouver les plans. Les plans se trouvaient dans la maison d'un contremaître de la {link:venture-company}KapitalRisk{/link} dans la {link:stranglethorn-vale}Vallée de Strangleronce{/link}, qui avait monté le nouveau régulateur sur ses déchiqueteuses. Quand les plans parvinrent enfin à Pozzik, ce n'étaient que des dessins. Il fut satisfait malgré tout, car il pouvait désormais améliorer la conception depuis la base.]=],
		},
		{
			title = "Suivre le rythme",
			hint = "Aidez Pozzik à apprendre le secret de la vitesse des gnomes.",
			text = [=[Les voitures gnomes étaient devenues plus rapides, et pourtant chaque plan que Pozzik pouvait voir était le même qu'avant. Il en conclut que les gnomes avaient trouvé un nouveau matériau. Pendant que Zamek créait une diversion, les plans de Rizzle Brassbolts lui furent pris sous le nez. Ils parlaient d'indurium, un minerai des fouilles naines d'{link:uldaman}Uldaman{/link} qui résiste à une grande chaleur, et dont un morceau servait de presse-papiers.]=],
		},
	},
	mentions = {
		{ text = "Alléger la charge" },
		{ text = "Parrainage gobelin" },
		{ text = "Parrainage gobelin, les plans rapportés" },
		{ text = "Le dix-huitième pilote" },
		{ text = "Suivre le rythme" },
		{ text = "Les schémas de Rizzle" },
		{ text = "Minerai d'indurium" },
	},
	bonds = {
		{ id = "razzeric", name = "Razzeric", note = "le pilote de l'équipe" },
		{ id = "gazlowe", name = "Gazlowe", note = "un parrain" },
		{ id = "fizzle-brassbolts", name = "Fizzle Brassbolts", note = "un rival" },
		{ id = "race-master-kronkrider", name = "Maître de course Kronkrider", note = "dirige la piste" },
	},
})

Translate("frFR", "razzeric", {
	title = "Razzeric",
	subtitle = "Le dix-huitième pilote",
	found = "Les stands gobelins de la Piste des mirages",
	hint = [=[Parlez au pilote gobelin qui aime plus de puissance qu'il n'est bon pour lui.]=],
	allegiance = "Équipe de course gobeline",
	sections = {
		{
			title = "Résumé",
			text = [=[Razzeric est le pilote de l'équipe de course gobeline, le dix-huitième à occuper ce siège. Autrefois, il faisait les courses dans les stands. Aujourd'hui, il pilote, et quand {link:pozzik}Pozzik{/link} a fini chaque bolide, Razzeric desserre les commandes, allège le châssis et ajoute du feu. Pozzik a placé un seau de sable sous son siège. Razzeric ne peut le lui pardonner.]=],
		},
		{
			title = "Importance",
			text = [=[Razzeric est la raison pour laquelle les gobelins gagnent quand ils gagnent, et la raison pour laquelle ils brûlent quand ils brûlent. Son propre ingénieur à {link:gadgetzan}Gadgetzan{/link} se demanda à voix haute si le dix-neuvième pilote vaudrait quelque chose.]=],
		},
	},
	chapters = {
		{
			title = "La sécurité d'abord",
			hint = "Faites retirer la sécurité du propulseur de Razzeric.",
			text = [=[Razzeric commanda un propulseur au seaforium à {link:shreev}Shreev{/link} du Gizmorium de {link:gadgetzan}Gadgetzan{/link}, en {link:tanaris}Tanaris{/link}. Le zeppelin qui le transportait s'écrasa dans le {link:dustwallow-marsh}Marécage d'Âprefange{/link}, et quand le propulseur fut enfin retrouvé, sa sécurité était toujours en place. Razzeric le renvoya. Shreev, qui l'avait déjà rendu bien plus dangereux qu'il n'était sage, retira la sécurité.]=],
		},
	},
	mentions = {
		{ text = "Le dix-huitième pilote" },
		{ text = "Les réglages de Razzeric" },
		{ text = "La sécurité d'abord" },
		{ text = "La sécurité d'abord, le propulseur rendu" },
	},
	bonds = {
		{ id = "pozzik", name = "Pozzik", note = "son mécanicien" },
	},
})

Translate("frFR", "fizzle-brassbolts", {
