			text = [=[Fizzle Brassbolts a plus de plans pour sa voiture-fusée qu'il ne pourra jamais en construire, et il veut tous les essayer. Il travaille sur un carburant qui brûle plus chaud que tous ceux d'avant, et sur un moteur qui, jure-t-il, fera voler la voiture. Avec ses frères Wizzle et Rizzle, il mène l'équipe {link:gnomes}gnome{/link} de {link:mirage-raceway}la Piste des mirages{/link}.]=],
		},
		{
			title = "Importance",
			text = [=[La quête de pistons capables de survivre à son moteur mena Fizzle jusqu'à {link:martek-the-exiled}Martek l'Exilé{/link} dans les {link:badlands}Terres ingrates{/link}, et de Martek jusqu'à l'indurium. Cette découverte rendit les voitures gnomes plus rapides que jamais, et les gobelins le remarquèrent.]=],
		},
	},
	mentions = {
		{ text = "Venin des {link:the-shimmering-flats}Salines{/link}" },
		{ text = "{link:martek-the-exiled}Martek l'Exilé{/link}" },
		{ text = "Des nouvelles pour Fizzle" },
		{ text = "Livraison aux gnomes" },
	},
	bonds = {
