		{ id = "pozzik", name = "Pozzik", note = "son rival" },
		{ id = "kravel-koalbeard", name = "Kravel Koalbeard", note = "honora sa commande de pièces" },
	},
})

Translate("frFR", "wizzle-brassbolts", {
	title = "Wizzle Brassbolts",
	subtitle = "Le Brassbolts prudent",
	found = "Les stands gnomes de la Piste des mirages",
