Translate("frFR", "kravel-koalbeard", {
	title = "Kravel Koalbeard",
	subtitle = "Trafiquant de la Piste des mirages",
	found = "À côté des stands gnomes de la Piste des mirages",
	hint = [=[Parlez au trafiquant qui achète des épaves et vend des faveurs sur la Piste.]=],
	allegiance = "Sa propre bourse",
	aliases = { "Kravel" },
	sections = {
		{
			title = "Résumé",
			text = [=[Kravel Koalbeard se fait un métier de procurer aux gens ce dont ils ont besoin, et de prendre sa part au passage. Il achète les épaves des bolides accidentés et les revend à l'équipe qui voudra payer. Il honore les commandes des gnomes, et il garde un peu de chacune pour lui. Il croit qu'il y a toujours du profit à tirer du malheur d'autrui, et il le dit volontiers.]=],
		},
		{
			title = "Importance",
			text = [=[Kravel est l'envers de {link:mirage-raceway}la Piste des mirages{/link}. Par lui, la rivalité des gobelins et des gnomes devient un commerce de secrets, de pots-de-vin et de bière droguée, et son influence s'étend de {link:ratchet}Ratchet{/link} à {link:booty-bay}Baie-du-Butin{/link}.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il achète la ferraille des bolides accidentés dans les {link:the-shimmering-flats}Salines{/link}.
• Il préleva une petite pièce sur la commande de pièces des gnomes avant de la livrer.
• Il apprit un secret du pilote gobelin Nazz Steamboil et comptait vendre son silence.
• Il envoya une caisse de munitions spéciales à son vieux client {link:hemet-nesingwary}Hemet Nesingwary{/link} à {link:stranglethorn-vale}Strangleronce{/link}.]=],
		},
		{
			title = "Non consigné",
			text = [=[On a peu écrit sur l'origine de Kravel, ni sur qui paie son ardoise.]=],
		},
	},
	chapters = {
		{
			title = "Le secret du pilote",
			hint = "Apprenez la vérité sur le pilote gobelin Nazz Steamboil.",
			text = [=[Kravel avait entendu dire que le pilote gobelin Nazz Steamboil n'avait pas toujours porté ce nom. Il fit appel à {link:krazek}Krazek{/link}, le colporteur de rumeurs de {link:booty-bay}Baie-du-Butin{/link}, qui paya en faveurs et avec une rare bouteille de vin elfique pour apprendre pourquoi. Krazek jugea le secret trop dangereux pour s'en servir lui-même. Pas Kravel. Il estima que Nazz paierait une petite fortune pour le garder caché.]=],
		},
		{
			title = "La Fool's Stout",
			hint = [=[Aidez Kravel à éprouver une manigance contre les équipes des stands.]=],
			text = [=[Avec {link:crank-fizzlebub}Crank Fizzlebub{/link} de {link:booty-bay}Baie-du-Butin{/link}, Kravel concocta une manigance. Fizzlebub mélangea une stout avec le breuvage que le troll {link:zanzil-the-outcast}Zanzil{/link} donne à ses serviteurs sans esprit, et la levure s'y emballa. Kravel offrit la Fool's Stout à l'une des équipes des stands la veille d'une course, et il plaça son pari. Cela marcha, et il en espéra davantage.]=],
		},
	},
	mentions = {
		{ text = "Pièces de voiture-fusée" },
		{ text = "Le maître des quais Dizzywig" },
		{ text = "Des pièces pour Kravel" },
		{ text = "Livraison aux gnomes" },
		{ text = "Le colporteur de rumeurs" },
		{ text = "Des rumeurs pour Kravel" },
		{ text = "Retour à {link:booty-bay}Baie-du-Butin{/link}" },
		{ text = "Soûler les gnomes" },
		{ text = "Soûler les gobelins" },
		{ text = "Faire son rapport à {link:crank-fizzlebub}Fizzlebub{/link}" },
		{ text = "{link:hemet-nesingwary}Hemet Nesingwary{/link}" },
	},
	bonds = {
		{ id = "fizzle-brassbolts", name = "Fizzle Brassbolts", note = "un client qu'il a floué" },
		{ id = "crank-fizzlebub", name = "Crank Fizzlebub", note = "son complice en manigances" },
		{ id = "krazek", name = "Krazek", note = "lui vendit un secret" },
		{ id = "hemet-nesingwary", name = "Hemet Nesingwary", note = "un vieux client" },
	},
})

Translate("frFR", "race-master-kronkrider", {
	title = "Maître de course Kronkrider",
	subtitle = "Maître de la Piste des mirages",
	found = "La tribune de la Piste des mirages",
	hint = "Parlez au maître du circuit des Salines.",
	allegiance = "Piste des mirages",
	aliases = { "Kronkrider" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le maître de course Kronkrider règne sur {link:mirage-raceway}la Piste des mirages{/link}. Il organise les courses, entretient la piste et règle les querelles de deux équipes qui se feraient volontiers sauter l'une l'autre. Après que le bolide des gobelins, Red Thunder, eut percuté un basilic sur la piste, il engagea le maître de piste Zherin pour éclaircir les bêtes des {link:the-shimmering-flats}Salines{/link} avant chaque course.]=],
		},
